import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, UnauthorizedException, UseGuards } from "@nestjs/common"
import { ClsModule, ClsService } from "nestjs-cls"

const tokens: Record<string, { id: number; name: string }> = { t1: { id: 1, name: "Laylo" } }

@Injectable()
class AuthGuard implements CanActivate {
    constructor(private readonly cls: ClsService) {}
    canActivate(ctx: ExecutionContext) {
        const user = tokens[ctx.switchToHttp().getRequest().headers["x-token"]]
        if (!user) throw new UnauthorizedException()
        this.cls.set("user", user)
        return true
    }
}

