import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ClsModule, ClsService } from "nestjs-cls"

@Injectable()
class UnitOfWork {
    constructor(private readonly cls: ClsService) {}
    run<T>(fn: () => Promise<T>) {
        return this.cls.run(async () => {
            this.cls.set("tx", { ops: [] as string[] })
            const result = await fn()
            console.log("commit:", this.cls.get("tx").ops)
            return result
        })
    }
    record(op: string) { this.cls.get("tx").ops.push(op) }
}

@Injectable() class UsersRepo { constructor(private readonly uow: UnitOfWork) {} save(n: string) { this.uow.record(`INSERT user ${n}`) } }
@Injectable() class WalletsRepo { constructor(private readonly uow: UnitOfWork) {} create(n: string) { this.uow.record(`INSERT wallet ${n}`) } }

@Module({ imports: [ClsModule.forRoot({ global: true })], providers: [UnitOfWork, UsersRepo, WalletsRepo] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const uow = app.get(UnitOfWork), users = app.get(UsersRepo), wallets = app.get(WalletsRepo)
    await uow.run(async () => { users.save("ali"); wallets.create("ali") })
    await app.close()
}
main()

