@Injectable()
class RemindersService {
    constructor(private readonly registry: SchedulerRegistry) {}
    add(name: string, cron: string, text: string) {
        const job = new CronJob(cron, () => console.log(`⏰ ${text}`))
        this.registry.addCronJob(name, job)
        job.start()
    }
    remove(name: string) { this.registry.deleteCronJob(name) }
    list() { return [...this.registry.getCronJobs().keys()] }
}

