const sharedLocks = new Map<string, number>()

@Injectable()
class ReportJob {
    constructor(private readonly instance: string) {}
    async run(now: number) {
        const lockUntil = sharedLocks.get("daily-report") ?? 0
        if (lockUntil > now) return `${this.instance}: o'tkazib yuborildi (boshqa server bajarmoqda)`
        sharedLocks.set("daily-report", now + 60_000)
        return `${this.instance}: hisobot yaratildi`
    }
}

