import { CronTime } from "cron"

const from = new Date("2024-10-07T08:50:00+05:00")
function nextRuns(expr: string, n: number, tz = "Asia/Tashkent", fmt = "ccc dd.LL HH:mm") {
    const t = new CronTime(expr, tz)
    const out: string[] = []
    let d = from
    for (let i = 0; i < n; i++) { const next = t.getNextDateFrom(d, tz); out.push(next.setZone(tz).toFormat(fmt)); d = next.toJSDate() }
    return out
}
