import { CronJob } from "cron"

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))
async function demo(waitForCompletion: boolean) {
    let runs = 0
    const job = CronJob.from({ cronTime: "0 0 1 1 *", onTick: async () => { runs++; await sleep(30) }, start: false, waitForCompletion })
    await Promise.all([job.fireOnTick(), job.fireOnTick(), job.fireOnTick()])
    console.log(`waitForCompletion=${waitForCompletion}: bajarildi ${runs} marta`)
}

async function main() {
    await demo(false)
    await demo(true)
}
