import { Cron, ScheduleModule, SchedulerRegistry } from "@nestjs/schedule"

@Injectable() class Tasks {
    @Cron("*/5 * * * *", { name: "a" }) a() {}
    @Cron("0 * * * *", { name: "b" }) b() {}
    @Cron("0 0 * * *", { name: "c" }) c() {}
}
@Module({ imports: [ScheduleModule.forRoot()], providers: [Tasks] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const r = app.get(SchedulerRegistry)
    const state = () => [...r.getCronJobs()].map(([n, j]) => `${n}:${j.isActive ? "on" : "off"}`).join(" ")
    console.log("oldin:", state())
    r.getCronJobs().forEach(j => j.stop())
    console.log("maintenance:", state())
    r.getCronJobs().forEach(j => j.start())
    console.log("qayta:", state())
    await app.close()
}
main()

