import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ScheduleModule, SchedulerRegistry } from "@nestjs/schedule"

@Injectable() class Reminders {
    sent: string[] = []
    constructor(private registry: SchedulerRegistry) {}
    schedule(userId: number, ms: number) { this.registry.addTimeout(`reminder:${userId}`, setTimeout(() => { this.sent.push(`user ${userId}`); this.registry.deleteTimeout(`reminder:${userId}`) }, ms)) }
    cancel(userId: number) { if (this.registry.doesExist("timeout", `reminder:${userId}`)) this.registry.deleteTimeout(`reminder:${userId}`) }
}
@Module({ imports: [ScheduleModule.forRoot()], providers: [Reminders] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const r = app.get(Reminders)
    r.schedule(1, 20); r.schedule(2, 20); r.schedule(3, 20)
    r.cancel(2)
    console.log("Rejadagilar:", app.get(SchedulerRegistry).getTimeouts())
    await new Promise(res => setTimeout(res, 50))
    console.log("Yuborildi:", r.sent)
    await app.close()
}
main()

