const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))
async function measure(kind: "interval" | "recursive") {
    let active = 0, maxActive = 0, stop = false
    const work = async () => { active++; maxActive = Math.max(maxActive, active); await sleep(35); active-- }
    if (kind === "interval") {
        const id = setInterval(work, 10)
        await sleep(120); clearInterval(id)
    } else {
        const loop = async () => { if (stop) return; await work(); setTimeout(loop, 10) }
        loop(); await sleep(120); stop = true
    }
    await sleep(60)
    console.log(`${kind.padEnd(9)}: bir vaqtda 1 tadan ko'p ish — ${maxActive > 1}`)
}

async function main() { await measure("interval"); await measure("recursive") }
main()

