@Injectable()
class InMemoryQueue {
    private jobs: { id: number; data: { email: string } }[] = []
    private nextId = 1
    processed: string[] = []
    add(data: { email: string }) {
        const job = { id: this.nextId++, data }
        this.jobs.push(job)
        setTimeout(() => this.work(), 20)   // fonda
        return job.id
    }
    private work() {
        const job = this.jobs.shift()
        if (job) this.processed.push(`#${job.id} → ${job.data.email}`)
    }
}

