// BullMQ'dagi { attempts, backoff: { type: "exponential", delay } } g'oyasi — xotirada
type Job = { id: number; attempts: number; maxAttempts: number }

async function processWithRetry(job: Job, handler: (j: Job) => Promise<void>, baseDelay: number) {
    while (true) {
        job.attempts++
        try {
            await handler(job)
            console.log(`#${job.id}: ${job.attempts}-urinishda muvaffaqiyatli`)
            return
        } catch (e) {
            if (job.attempts >= job.maxAttempts) { console.log(`#${job.id}: ${job.attempts} urinishdan keyin FAILED — ${(e as Error).message}`); return }
            const delay = baseDelay * 2 ** (job.attempts - 1)
            console.log(`#${job.id}: xato, ${delay}ms dan keyin qayta`)
            await new Promise(r => setTimeout(r, delay))
        }
    }
}

async function main() {
    let calls = 0
    await processWithRetry({ id: 1, attempts: 0, maxAttempts: 5 }, async () => { if (++calls < 3) throw new Error("SMTP band") }, 10)
    await processWithRetry({ id: 2, attempts: 0, maxAttempts: 3 }, async () => { throw new Error("email manzili yo'q") }, 10)
}
main()

async function runQueue<T>(items: T[], concurrency: number, worker: (x: T) => Promise<void>) {
    const queue = [...items]
    let active = 0, maxActive = 0
    await Promise.all(Array.from({ length: concurrency }, async () => {
        while (queue.length) {
            const item = queue.shift()!
            active++; maxActive = Math.max(maxActive, active)
            await worker(item)
            active--
        }
    }))
    return maxActive
}

async function main() {
    const start = Date.now()
    const done: number[] = []
    const max = await runQueue([1, 2, 3, 4, 5, 6], 3, async n => { await new Promise(r => setTimeout(r, 50)); done.push(n) })
    const elapsed = Date.now() - start
    console.log("bajarildi:", done.length, "ta | bir vaqtdagi maksimum:", max)
    console.log("vaqt ~", elapsed < 200 ? "2 x 50ms (parallel)" : "6 x 50ms (ketma-ket)")
    console.log("BullMQ'da: @Processor('queue', { concurrency: 3 })")
}
main()

type DelayedJob = { name: string; runAt: number }

class DelayedQueue {
    private jobs: DelayedJob[] = []
    constructor(private now: () => number) {}
    add(name: string, delayMs: number) { this.jobs.push({ name, runAt: this.now() + delayMs }) }
    due() {
        const ready = this.jobs.filter(j => j.runAt <= this.now()).map(j => j.name)
        this.jobs = this.jobs.filter(j => j.runAt > this.now())
        return ready
    }
}

