import { Injectable, Module, OnModuleDestroy } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Job = { id: number; name: string; data: { to: string } }

@Injectable()
class MailQueue implements OnModuleDestroy {
    private jobs: Job[] = []
    private id = 0
    private handler?: (j: Job) => Promise<void>
    private timer = setInterval(() => void this.tick(), 5)
    add(name: string, data: Job["data"]) { this.jobs.push({ id: ++this.id, name, data }); return this.id }
    process(handler: (j: Job) => Promise<void>) { this.handler = handler }
    private async tick() { const j = this.jobs.shift(); if (j && this.handler) await this.handler(j) }
    onModuleDestroy() { clearInterval(this.timer) }
}

