async function runWithTimeout<T>(name: string, work: () => Promise<T>, ms: number) {
    let timer: NodeJS.Timeout | undefined
    const timeout = new Promise<never>((_, rej) => { timer = setTimeout(() => rej(new Error(`${ms} ms'da tugamadi`)), ms) })
    try { console.log(name, "→ completed:", await Promise.race([work(), timeout])) }
    catch (e) { console.log(name, "→ failed:", (e as Error).message) }
    finally { clearTimeout(timer) }
}

