class Worker {
    private closing = false
    private current: Promise<void> = Promise.resolve()
    done: string[] = []
    constructor(private queue: string[]) {}
    start() { this.loop() }
    private async loop() {
        while (!this.closing && this.queue.length) {
            const job = this.queue.shift()!
            this.current = sleep(20).then(() => { this.done.push(job) })
            await this.current
        }
    }
    get remaining() { return this.queue.length }
    async close() { this.closing = true; await this.current }
}

