class MinHeap<T> {
    private a: { p: number; v: T }[] = []
    push(p: number, v: T) {
        this.a.push({ p, v })
        let i = this.a.length - 1
        while (i > 0) { const par = (i - 1) >> 1; if (this.a[par].p <= this.a[i].p) break; [this.a[par], this.a[i]] = [this.a[i], this.a[par]]; i = par }
    }
    pop() {
        const top = this.a[0], last = this.a.pop()!
        if (this.a.length) {
            this.a[0] = last
            let i = 0
            for (;;) {
                const l = 2 * i + 1, r = l + 1
                let m = i
                if (l < this.a.length && this.a[l].p < this.a[m].p) m = l
                if (r < this.a.length && this.a[r].p < this.a[m].p) m = r
                if (m === i) break
                ;[this.a[m], this.a[i]] = [this.a[i], this.a[m]]; i = m
            }
        }
        return top?.v
    }
    get size() { return this.a.length }
}
