class CircuitBreaker {
    private failures = 0
    private openedAt: number | null = null
    constructor(private threshold: number, private cooldown: number, private now: () => number) {}
    async call<T>(fn: () => Promise<T>) {
        if (this.openedAt !== null) {
            if (this.now() - this.openedAt < this.cooldown) throw new Error("circuit OPEN — urinib ko'rilmadi")
            this.openedAt = null
        }
        try { const r = await fn(); this.failures = 0; return r }
        catch (e) { if (++this.failures >= this.threshold) this.openedAt = this.now(); throw e }
    }
}
