class Semaphore {
    private waiting: (() => void)[] = []
    constructor(private free: number) {}
    async acquire() { if (this.free > 0) { this.free--; return } await new Promise<void>(r => this.waiting.push(r)) }
    release() { const next = this.waiting.shift(); if (next) next(); else this.free++ }
}
const sem = new Semaphore(2)
let active = 0, maxActive = 0

async function job(id: number) {
    await sem.acquire()
    active++; maxActive = Math.max(maxActive, active)
    await sleep(10)
    active--
    sem.release()
    return id
}

