class TransientError extends Error {}
class FatalError extends Error {}
async function processWithRetry(name: string, fn: (attempt: number) => Promise<string>, max = 3) {
    for (let attempt = 1; ; attempt++) {
        try { return console.log(`${name}: completed (${attempt}-urinish) →`, await fn(attempt)) }
        catch (e) {
            const retry = e instanceof TransientError && attempt < max
            console.log(`${name}: ${attempt}-urinish ${(e as Error).message} → ${retry ? "qayta" : "failed"}`)
            if (!retry) return
        }
    }
}

