import { Injectable, Module, OnModuleInit } from "@nestjs/common"
import { DiscoveryModule, DiscoveryService, MetadataScanner, NestFactory } from "@nestjs/core"

const PROCESS = "queue:process"
const Process = (jobName: string) => (target: object, key: string | symbol) => Reflect.defineMetadata(PROCESS, jobName, target, key)
@Injectable() class MailProcessor {
    @Process("welcome") welcome(d: { to: string }) { return `welcome → ${d.to}` }
    @Process("reset") reset(d: { to: string }) { return `reset → ${d.to}` }
