@Injectable() class QueueRunner implements OnModuleInit {
    private handlers = new Map<string, (d: { to: string }) => string>()
    constructor(private discovery: DiscoveryService, private scanner: MetadataScanner) {}
    onModuleInit() {
        for (const w of this.discovery.getProviders()) {
            const inst = w.instance as Record<string, Function> | undefined
            if (!inst || typeof inst !== "object") continue
            for (const m of this.scanner.getAllMethodNames(Object.getPrototypeOf(inst))) {
                const job = Reflect.getMetadata(PROCESS, Object.getPrototypeOf(inst), m)
                if (job) this.handlers.set(job, inst[m].bind(inst) as (d: { to: string }) => string)
            }
        }
        console.log("Ro'yxatga olingan ishlar:", [...this.handlers.keys()])
    }
    run(name: string, data: { to: string }) { return this.handlers.get(name)?.(data) ?? `handler yo'q: ${name}` }
}
