class Order {
    private events: { name: string; payload: object }[] = []
    status = "new"
    constructor(public id: number) {}
    pay() { this.status = "paid"; this.events.push({ name: "order.paid", payload: { id: this.id, what: "to'landi" } }) }
    ship() { this.status = "shipped"; this.events.push({ name: "order.shipped", payload: { id: this.id, what: "jo'natildi" } }) }
    pullEvents() { const e = this.events; this.events = []; return e }
}
@Injectable() class OrdersRepo {
    constructor(private emitter: EventEmitter2) {}
    save(o: Order) {
        console.log(`saqlandi: #${o.id} (${o.status})`)
        for (const e of o.pullEvents()) this.emitter.emit(e.name, e.payload)
    }
}
