import { EventEmitter2, EventEmitterModule, OnEvent } from "@nestjs/event-emitter"

type OutboxRow = { id: number; event: string; payload: object; sent: boolean }
@Injectable() class Outbox {
    rows: OutboxRow[] = []
    add(event: string, payload: object) { this.rows.push({ id: this.rows.length + 1, event, payload, sent: false }) }
}
@Injectable() class OrdersService {
    constructor(private outbox: Outbox) {}
    create(id: number) { /* bitta tranzaksiyada: order + outbox yozuvi */ this.outbox.add("order.created", { id }) }
}
@Injectable() class OutboxRelay {
    constructor(private outbox: Outbox, private emitter: EventEmitter2) {}
    flush() { for (const r of this.outbox.rows.filter(r => !r.sent)) { this.emitter.emit(r.event, r.payload); r.sent = true } }
}
@Injectable() class Listener { @OnEvent("order.created") on(p: { id: number }) { console.log("  qabul qilindi: order", p.id) } }
@Module({ imports: [EventEmitterModule.forRoot()], providers: [Outbox, OrdersService, OutboxRelay, Listener] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    app.get(OrdersService).create(1); app.get(OrdersService).create(2)
    console.log("outbox:", app.get(Outbox).rows.map(r => `#${r.id} sent=${r.sent}`))
    app.get(OutboxRelay).flush()
    console.log("relay'dan keyin:", app.get(Outbox).rows.map(r => `#${r.id} sent=${r.sent}`))
    await app.close()
}
main()

