import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { EventEmitter2, EventEmitterModule } from "@nestjs/event-emitter"
import { bufferCount, fromEvent, map } from "rxjs"

@Module({ imports: [EventEmitterModule.forRoot()] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const e = app.get(EventEmitter2)
    fromEvent(e, "page.view")
        .pipe(map(p => (p as { path: string }).path), bufferCount(3))
        .subscribe(batch => console.log("3 talik paket analitikaga:", batch))
    for (const path of ["/", "/menu", "/cart", "/checkout", "/", "/profile", "/menu"]) e.emit("page.view", { path })
    await app.close()
}
