import { Body, Controller, Get, Inject, Injectable, Module, Patch } from "@nestjs/common"
import { CACHE_MANAGER, CacheModule } from "@nestjs/cache-manager"
import type { Cache } from "cache-manager"

@Injectable()
class SettingsService {
    private db = { theme: "light" }
    constructor(@Inject(CACHE_MANAGER) private readonly cache: Cache) {}
    async get() {
        const hit = await this.cache.get<object>("settings")
        if (hit) return { ...hit, source: "kesh" }
        await this.cache.set("settings", { ...this.db })
        return { ...this.db, source: "baza" }
    }
    async update(theme: string) {
        this.db.theme = theme
        await this.cache.del("settings") // eski qiymat qaytib qolmasligi uchun
        return this.db
    }
}

@Controller("settings")
class SettingsController {
    constructor(private readonly s: SettingsService) {}
    @Get() get() { return this.s.get() }
    @Patch() update(@Body("theme") t: string) { return this.s.update(t) }
}

@Module({ imports: [CacheModule.register()], controllers: [SettingsController], providers: [SettingsService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/settings")
    await http.get("/settings")
    await http.patch("/settings", { theme: "dark" })
    await http.get("/settings")
    await http.close()
}
main()

