import { CACHE_MANAGER, CacheModule } from "@nestjs/cache-manager"
import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import type { Cache } from "cache-manager"

@Injectable()
class ReportService {
    computations = 0
    private pending = new Map<string, Promise<unknown>>()
    constructor(@Inject(CACHE_MANAGER) private readonly cache: Cache) {}
    private async compute() { this.computations++; await new Promise(r => setTimeout(r, 30)); return { total: 999 } }
    async get(key: string) {
        const hit = await this.cache.get(key)
        if (hit) return hit
        if (!this.pending.has(key)) {
            this.pending.set(key, this.compute().then(async v => { await this.cache.set(key, v, 60_000); this.pending.delete(key); return v }))
        }
        return this.pending.get(key)
    }
}
@Module({ imports: [CacheModule.register()], providers: [ReportService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(ReportService)
    await Promise.all(Array.from({ length: 10 }, () => s.get("daily")))
    console.log("10 ta parallel so'rov, og'ir hisob:", s.computations, "marta")
    await app.close()
}
