import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { CACHE_MANAGER, CacheModule } from "@nestjs/cache-manager"
import type { Cache } from "cache-manager"

@Injectable() class TaggedCache {
    private tags = new Map<string, Set<string>>()
    constructor(@Inject(CACHE_MANAGER) private cache: Cache) {}
    async set(key: string, value: unknown, tags: string[]) {
        await this.cache.set(key, value)
        for (const t of tags) this.tags.set(t, (this.tags.get(t) ?? new Set()).add(key))
    }
    get(key: string) { return this.cache.get(key) }
    async invalidate(tag: string) {
        const keys = [...(this.tags.get(tag) ?? [])]
        await this.cache.mdel(keys)
        this.tags.delete(tag)
        return keys
    }
}
@Module({ imports: [CacheModule.register()], providers: [TaggedCache] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const c = app.get(TaggedCache)
    await c.set("products:page:1", ["non"], ["products"])
    await c.set("products:page:2", ["sut"], ["products"])
    await c.set("user:1", { name: "Ali" }, ["users"])
    console.log("o'chirildi:", await c.invalidate("products"))
    console.log("page:1 →", await c.get("products:page:1"), "| user:1 →", await c.get("user:1"))
    await app.close()
}
