import { createHash } from "node:crypto"

const BASE_TTL = 600
function ttlWithJitter(key: string, spreadPercent = 10) {
    const n = createHash("md5").update(key).digest().readUInt16BE(0) / 0xffff
    const spread = BASE_TTL * (spreadPercent / 100)
    return Math.round(BASE_TTL - spread + n * spread * 2)
}
for (const key of ["product:1", "product:2", "product:3", "product:4"]) console.log(key, "→", ttlWithJitter(key), "s")

