import { CACHE_MANAGER, CacheModule } from "@nestjs/cache-manager"
import type { Cache } from "cache-manager"

@Injectable() class TwoLevelCache {
    private l1 = new Map<string, unknown>()
    constructor(@Inject(CACHE_MANAGER) private l2: Cache) {}
    async get(key: string) {
        if (this.l1.has(key)) return { from: "L1", value: this.l1.get(key) }
        const v = await this.l2.get(key)
        if (v !== undefined) { this.l1.set(key, v); return { from: "L2", value: v } }
        return { from: "miss", value: null }
    }
    async set(key: string, v: unknown) { await this.l2.set(key, v) }
}
