@Injectable() class OtpService {
    constructor(@Inject(CACHE_MANAGER) private cache: Cache) {}
    async verify(phone: string, code: string) {
        const key = `otp-tries:${phone}`
        const tries = ((await this.cache.get<number>(key)) ?? 0) + 1
        await this.cache.set(key, tries, 5 * 60_000)
        if (tries > 3) return "bloklandi, 5 daqiqa kuting"
        return code === "1234" ? "to'g'ri" : `noto'g'ri (${tries}/3)`
    }
}
