import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { CACHE_MANAGER, CacheModule } from "@nestjs/cache-manager"
import type { Cache } from "cache-manager"

let computed = 0
function countPrimes(n: number) {
    computed++
    const sieve = new Uint8Array(n + 1)
    let count = 0
    for (let i = 2; i <= n; i++) { if (sieve[i]) continue; count++; for (let j = i * i; j <= n; j += i) sieve[j] = 1 }
    return count
}
@Injectable() class MathService {
    constructor(@Inject(CACHE_MANAGER) private cache: Cache) {}
    primes(n: number) { return this.cache.wrap(`primes:${n}`, () => countPrimes(n)) }
}
@Module({ imports: [CacheModule.register()], providers: [MathService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const m = app.get(MathService)
    for (const n of [1_000_000, 1_000_000, 100]) console.log(`primes(${n}) =`, await m.primes(n))
    console.log("Haqiqiy hisoblashlar:", computed)
    await app.close()
}
