class TtlCache<V> {
    private data = new Map<string, { value: V; until: number }>()
    constructor(private now: () => number) {}
    set(key: string, value: V, ttlMs: number) { this.data.set(key, { value, until: this.now() + ttlMs }) }
    get(key: string) {
        const e = this.data.get(key)
        if (!e) return undefined
        if (e.until <= this.now()) { this.data.delete(key); return undefined }
        return e.value
    }
}
let fakeNow = 0
const c = new TtlCache<string>(() => fakeNow)
c.set("otp", "4821", 1000)
console.log("0 ms:", c.get("otp"))
fakeNow = 999; console.log("999 ms:", c.get("otp"))
fakeNow = 1000; console.log("1000 ms:", c.get("otp"))

const cache = new WeakMap<object, number>()
let computed = 0
function totalPrice(order: { items: { price: number; qty: number }[] }) {
    const hit = cache.get(order)
    if (hit !== undefined) return hit
    computed++
    const sum = order.items.reduce((s, i) => s + i.price * i.qty, 0)
    cache.set(order, sum)
    return sum
}
const order = { items: [{ price: 4000, qty: 2 }, { price: 12000, qty: 1 }] }
console.log(totalPrice(order), totalPrice(order), totalPrice({ items: [{ price: 5, qty: 1 }] }))
console.log("Hisoblashlar:", computed)

