import { Injectable, Module } from "@nestjs/common"
import { ConfigModule, ConfigService } from "@nestjs/config"
import { NestFactory } from "@nestjs/core"
import { plainToInstance } from "class-transformer"
import { IsEnum, IsInt, IsString, Max, Min, validateSync } from "class-validator"

enum Env { Development = "development", Production = "production" }

class EnvVars {
    @IsEnum(Env) NODE_ENV: Env
    @IsInt() @Min(1) @Max(65535) PORT: number
    @IsString() DATABASE_URL: string
}

function validate(config: Record<string, unknown>) {
    const vars = plainToInstance(EnvVars, config, { enableImplicitConversion: true })
    const errors = validateSync(vars, { skipMissingProperties: false })
    if (errors.length) throw new Error(errors.map(e => Object.values(e.constraints ?? {}).join(", ")).join("; "))
    return vars
}

