import { Module } from "@nestjs/common"
import { ConfigModule, ConfigService } from "@nestjs/config"
import { NestFactory } from "@nestjs/core"
import { plainToInstance, Transform } from "class-transformer"
import { IsBoolean, IsInt, validateSync } from "class-validator"

class Env {
    @Transform(({ value }) => Number(value)) @IsInt() PORT: number
    @Transform(({ value }) => value === "true") @IsBoolean() DEBUG: boolean
}

function validate(raw: Record<string, unknown>) {
    const env = plainToInstance(Env, raw)
    const errors = validateSync(env)
    if (errors.length) throw new Error(errors.map(e => Object.values(e.constraints!)).join("; "))
    return env
}

async function main() {
