const UNITS: Record<string, number> = { ms: 1, s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 }
function duration(raw: string) {
    const m = /^(\d+)(ms|s|m|h|d)$/.exec(raw.trim())
    if (!m) throw new Error(`Noto'g'ri davomiylik: ${raw}`)
    return Number(m[1]) * UNITS[m[2]]
}
for (const raw of ["30s", "15m", "2h", "7d", "10 min"]) {
    try { console.log(raw.padEnd(7), "→", duration(raw), "ms") } catch (e) { console.log(raw.padEnd(7), "→", (e as Error).message) }
}

const SIZE: Record<string, number> = { b: 1, kb: 1024, mb: 1024 ** 2, gb: 1024 ** 3 }
function bytes(raw: string) {
    const m = /^(\d+(?:\.\d+)?)\s*(b|kb|mb|gb)$/i.exec(raw.trim())
    if (!m) throw new Error(`Noto'g'ri hajm: ${raw}`)
    return Math.round(Number(m[1]) * SIZE[m[2].toLowerCase()])
}
for (const raw of ["512kb", "10mb", "1.5GB", "100"]) {
    try { console.log(raw.padEnd(6), "→", bytes(raw).toLocaleString("en-US"), "bayt") } catch (e) { console.log(raw.padEnd(6), "→", (e as Error).message) }
