const env: Record<string, string> = { APP__DB__HOST: "db.local", APP__DB__PORT: "5432", APP__CACHE__TTL: "60", OTHER: "x" }
function nested(prefix: string) {
    const out: Record<string, any> = {}
    for (const [key, value] of Object.entries(env)) {
        if (!key.startsWith(prefix + "__")) continue
        const path = key.slice(prefix.length + 2).toLowerCase().split("__")
        let node = out
        for (const p of path.slice(0, -1)) node = node[p] ??= {}
        node[path.at(-1)!] = value
    }
    return out
}
