import { Controller, FileTypeValidator, MaxFileSizeValidator, Module, ParseFilePipe, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

@Controller("avatar")
class AvatarController {
    @Post()
    @UseInterceptors(FileInterceptor("file"))
    upload(@UploadedFile(new ParseFilePipe({
        validators: [
            new MaxFileSizeValidator({ maxSize: 1024, message: "Fayl 1 KB dan katta bo'lmasin" }),
            new FileTypeValidator({ fileType: /^text\/plain$/, skipMagicNumbersValidation: true }),
        ],
    })) file: Express.Multer.File) {
        return { ok: true, size: file.size }
    }
}

@Module({ controllers: [AvatarController] })
class AppModule {}

async function send(url: string, content: BlobPart, type: string, name: string) {
    const form = new FormData()
    form.append("file", new Blob([content], { type }), name)
    const res = await fetch(url + "/avatar", { method: "POST", body: form })
    console.log(`${name.padEnd(10)} →`, res.status, await res.text())
}

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    await send(url, "kichik", "text/plain", "ok.txt")
    await send(url, "x".repeat(5000), "text/plain", "katta.txt")
    await send(url, "data", "application/zip", "arxiv.zip")
    await http.close()
}
main()

