import { basename } from "node:path"
import { randomUUID } from "node:crypto"

function safeFileName(original: string) {
    const base = basename(original.replaceAll("\\", "/"))          // "../../etc/passwd" → "passwd"
    const ext = (base.match(/\.[a-z0-9]{1,5}$/i)?.[0] ?? "").toLowerCase()
    return { stored: `${randomUUID().slice(0, 8)}${ext}`, cleaned: base.replace(/[^\w.\-]/g, "_") }
}

for (const name of ["rasm.PNG", "../../etc/passwd", "hisobot 2026 (final).pdf"]) {
