import { Controller, Module, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

@Controller("import")
class ImportController {
    @Post("csv") @UseInterceptors(FileInterceptor("file"))
    csv(@UploadedFile() file: Express.Multer.File) {
        const [header, ...rows] = file.buffer.toString("utf8").trim().split("\n")
        const cols = header.split(",")
        const items = rows.map(r => Object.fromEntries(r.split(",").map((v, i) => [cols[i], v])))
        const total = items.reduce((s, i) => s + Number(i.price) * Number(i.qty), 0)
        return { rows: items.length, total }
    }
}
