import { Controller, Headers, Module, PayloadTooLargeException, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

const QUOTA = 100
const used = new Map<string, number>()
@Controller("drive") class D {
    @Post() @UseInterceptors(FileInterceptor("file"))
    up(@UploadedFile() f: Express.Multer.File, @Headers("x-user") user: string) {
        const now = used.get(user) ?? 0
        if (now + f.size > QUOTA) throw new PayloadTooLargeException(`Kvota tugadi: ${now}/${QUOTA} bayt band`)
        used.set(user, now + f.size)
        return { band: `${now + f.size}/${QUOTA}` }
    }
}
@Module({ controllers: [D] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    for (const size of [40, 50, 30]) {
        const form = new FormData(); form.append("file", new Blob([Buffer.alloc(size)]), "f.bin")
        const res = await fetch(base + "/drive", { method: "POST", body: form, headers: { "x-user": "ali" } })
        console.log(`+${size} →`, res.status, await res.text())
    }
    await http.close()
}
main()

import { BadRequestException, Body, Controller, Module, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

const parts = new Map<string, Buffer[]>()
@Controller("chunks") class C {
    @Post() @UseInterceptors(FileInterceptor("chunk"))
    up(@UploadedFile() chunk: Express.Multer.File, @Body() b: { uploadId: string; index: string; total: string }) {
        const list = parts.get(b.uploadId) ?? []
        list[Number(b.index)] = chunk.buffer
        parts.set(b.uploadId, list)
        const received = list.filter(Boolean).length
        if (received < Number(b.total)) return { qabul: `${received}/${b.total}` }
        if (list.length !== Number(b.total)) throw new BadRequestException("Qismlar yetishmaydi")
        return { tayyor: true, mazmun: Buffer.concat(list).toString() }
    }
}
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const chunks = ["Salom, ", "bu katta ", "fayl!"]
    for (const i of [0, 2, 1]) {
        const form = new FormData()
        form.append("chunk", new Blob([chunks[i]]), `part${i}`); form.append("uploadId", "u1"); form.append("index", String(i)); form.append("total", "3")
        const res = await fetch(base + "/chunks", { method: "POST", body: form })
        console.log(`qism ${i} →`, await res.text())
    }
    await http.close()
}
main()

