import { Controller, ForbiddenException, Get, Module, Post, Query, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"
import { createHmac } from "node:crypto"

const SECRET = "upload-secret"
const NOW = 1_700_000_000
const sign = (key: string, exp: number) => createHmac("sha256", SECRET).update(`${key}:${exp}`).digest("hex").slice(0, 16)
@Controller("uploads") class U {
    @Get("url") url(@Query("key") key: string) { const exp = NOW + 300; return { url: `/uploads?key=${key}&exp=${exp}&sig=${sign(key, exp)}` } }
    @Post() @UseInterceptors(FileInterceptor("file"))
    up(@UploadedFile() f: Express.Multer.File, @Query() q: { key: string; exp: string; sig: string }) {
        if (Number(q.exp) < NOW) throw new ForbiddenException("Havola muddati tugagan")
        if (sign(q.key, Number(q.exp)) !== q.sig) throw new ForbiddenException("Imzo noto'g'ri")
        return { saqlandi: q.key, size: f.size }
    }
}
@Module({ controllers: [U] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const { data } = await http.get("/uploads/url?key=avatars/7.png")
    for (const url of [data.url, data.url.replace(/sig=\w+/, "sig=soxta")]) {
        const form = new FormData(); form.append("file", new Blob(["img"]), "7.png")
        const res = await fetch(base + url, { method: "POST", body: form })
        console.log("POST", url.includes("soxta") ? "(soxta imzo)" : "(to'g'ri imzo)", "→", res.status, await res.text())
    }
    await http.close()
}
main()

