import { Controller, Delete, Module, NotFoundException, Param, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"
import { diskStorage } from "multer"
import { existsSync, mkdtempSync, unlinkSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

const dir = mkdtempSync(join(tmpdir(), "del-"))
const files = new Map<string, string>()
let seq = 0
@Controller("files") class F {
    @Post() @UseInterceptors(FileInterceptor("file", { storage: diskStorage({ destination: dir, filename: (_r, _f, cb) => cb(null, `f${++seq}`) }) }))
    up(@UploadedFile() f: Express.Multer.File) { files.set(f.filename, f.path); return { id: f.filename } }
    @Delete(":id") del(@Param("id") id: string) {
        const path = files.get(id)
        if (!path) throw new NotFoundException("Fayl topilmadi")
        unlinkSync(path); files.delete(id)
        return { ochirildi: id, diskdaQoldimi: existsSync(path) }
    }
}
@Module({ controllers: [F] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const form = new FormData(); form.append("file", new Blob(["x"]), "a.txt")
    const res = await fetch((await http.app.getUrl()) + "/files", { method: "POST", body: form })
    const { id } = await res.json()
    await http.delete(`/files/${id}`)
    await http.delete(`/files/${id}`)
    await http.close()
}
main()

