import { map } from "rxjs"

const snake = (s: string) => s.replace(/[A-Z]/g, c => "_" + c.toLowerCase())
const deep = (v: unknown): unknown => Array.isArray(v) ? v.map(deep) : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [snake(k), deep(x)])) : v
@Injectable() class SnakeCase implements NestInterceptor { intercept(_: ExecutionContext, next: CallHandler) { return next.handle().pipe(map(deep)) } }
