function limitDepth(v: unknown, depth: number): unknown {
    if (v && typeof v === "object") {
        if (depth === 0) return Array.isArray(v) ? `[${v.length} ta element]` : "{...}"
        return Array.isArray(v) ? v.map(x => limitDepth(x, depth - 1)) : Object.fromEntries(Object.entries(v).map(([k, x]) => [k, limitDepth(x, depth - 1)]))
    }
    return v
}
