import type { Request } from "express"

@Controller({ path: "prices", version: "1" }) class PricesV1 { @Get() get() { return { choy: 25000 } } }
@Controller({ path: "prices", version: "2" }) class PricesV2 { @Get() get() { return { items: [{ sku: "choy", price: 25000 }] } } }
