const SUPPORTED = ["2", "1"]   // eng yangisi birinchi

async function main() {
    const http = await testApp(AppModule, app => app.enableVersioning({
        type: VersioningType.CUSTOM,
        extractor: (req: unknown) => {
            const accepted = String((req as Request).headers["accept-versions"] ?? "1").split(",").map(v => v.trim())
            return SUPPORTED.find(v => accepted.includes(v)) ?? "1"
        },
    }))
    await http.get("/feed", { "Accept-Versions": "1, 2, 3" })
    await http.get("/feed", { "Accept-Versions": "1" })
