import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors, VersioningType } from "@nestjs/common"

@Injectable()
class DeprecatedInterceptor implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const res = ctx.switchToHttp().getResponse()
        res.setHeader("Deprecation", "true")
        res.setHeader("Sunset", "Wed, 31 Dec 2026 23:59:59 GMT")
        res.setHeader("Link", '</v2/products>; rel="successor-version"')
        return next.handle()
    }
}

