import { ArgumentsHost, Catch, Controller, ExceptionFilter, Get, Module, NotFoundException, VersioningType } from "@nestjs/common"

const SUPPORTED = ["1", "2"]
@Catch(NotFoundException) class VersionHint implements ExceptionFilter {
    catch(e: NotFoundException, host: ArgumentsHost) {
        const req = host.switchToHttp().getRequest(), res = host.switchToHttp().getResponse()
        const m = /^\/v(\d+)\//.exec(req.url)
        if (m && !SUPPORTED.includes(m[1])) return res.status(404).json({ message: `API v${m[1]} mavjud emas`, supported: SUPPORTED.map(v => `v${v}`) })
        res.status(404).json(e.getResponse())
    }
}
@Controller({ path: "cats", version: SUPPORTED }) class C { @Get() c() { return ["Mosh"] } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => { app.enableVersioning({ type: VersioningType.URI }); app.useGlobalFilters(new VersionHint()) })
    await http.get("/v7/cats")
    await http.get("/v1/dogs")
    await http.close()
}
main()

