import { CanActivate, Controller, ExecutionContext, Get, GoneException, Injectable, Module, SetMetadata, UseGuards, VersioningType } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

let today = "2025-05-01"
const Sunset = (date: string) => SetMetadata("sunset", date)
@Injectable() class SunsetGuard implements CanActivate {
    constructor(private r: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const date = this.r.get<string>("sunset", ctx.getClass())
        if (date && today > date) throw new GoneException(`v1 ${date} sanasida o'chirilgan`)
        return true
    }
}
@Controller({ path: "cats", version: "1" }) @Sunset("2025-06-30") @UseGuards(SunsetGuard) class CatsV1 { @Get() c() { return ["Mosh"] } }
