import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, VersioningType } from "@nestjs/common"
import { APP_INTERCEPTOR } from "@nestjs/core"

const usage: Record<string, number> = {}
@Injectable() class VersionUsage implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const v = `v${Reflect.getMetadata("__version__", ctx.getClass())}`
        usage[v] = (usage[v] ?? 0) + 1
        return next.handle()
    }
}
@Controller({ path: "news", version: "1" }) class N1 { @Get() n() { return [] } }
@Controller({ path: "news", version: "2" }) class N2 { @Get() n() { return [] } }
@Module({ controllers: [N1, N2], providers: [{ provide: APP_INTERCEPTOR, useClass: VersionUsage }] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.enableVersioning({ type: VersioningType.URI }))
    for (const v of [2, 2, 1, 2, 2, 2, 1]) await http.get(`/v${v}/news`)
    const total = Object.values(usage).reduce((a, b) => a + b, 0)
