    lines: string[] = []
    log(m: unknown, ctx?: string) { this.lines.push(`LOG   [${ctx}] ${m}`) }
    error(m: unknown, _trace?: string, ctx?: string) { this.lines.push(`ERROR [${ctx}] ${m}`) }
    warn(m: unknown, ctx?: string) { this.lines.push(`WARN  [${ctx}] ${m}`) }
}
const logger = new Logger("Orders")
@Controller("orders") class O { @Get() list() { logger.log("ro'yxat so'raldi"); logger.warn("sekin so'rov"); return [] } }
@Module({ controllers: [O] }) class AppModule {}

async function main() {
    const mine = new ArrayLogger()
    const app = await NestFactory.create(AppModule, { logger: false })
    app.useLogger(mine)
    await app.init()
    app.get(O).list()
    console.log(mine.lines)
    await app.close()
}
main()

