class DedupLogger {
    private last?: string
    private repeat = 0
    log(msg: string) {
        if (msg === this.last) { this.repeat++; return }
        this.flush()
        console.log(msg)
        this.last = msg
    }
    flush() { if (this.repeat) console.log(`  ↑ yana ${this.repeat} marta takrorlandi`); this.repeat = 0 }
}
const log = new DedupLogger()
for (const m of ["Redis ulanmadi", "Redis ulanmadi", "Redis ulanmadi", "Redis ulandi", "so'rov keldi", "so'rov keldi"]) log.log(m)
log.flush()

function chain(e: unknown): string[] {
    const out: string[] = []
    let cur: unknown = e
    while (cur instanceof Error) { out.push(`${cur.name}: ${cur.message}`); cur = cur.cause }
    return out
}
try {
    try {
        try { throw new Error("ECONNREFUSED 10.0.0.5:5432") } catch (e) { throw new Error("DB ulanishi muvaffaqiyatsiz", { cause: e }) }
    } catch (e) { throw new Error("Buyurtmani saqlab bo'lmadi", { cause: e }) }
} catch (e) {
    chain(e).forEach((line, i) => console.log(`${"  ".repeat(i)}${i ? "↳ " : ""}${line}`))
}

import { ArgumentsHost, BadRequestException, Catch, Controller, ExceptionFilter, Get, HttpException, Module, UseFilters } from "@nestjs/common"

const logged: string[] = []
@Catch() class ServerErrorLogger implements ExceptionFilter {
    catch(e: unknown, host: ArgumentsHost) {
        const status = e instanceof HttpException ? e.getStatus() : 500
        const req = host.switchToHttp().getRequest()
        if (status >= 500) logged.push(`${req.method} ${req.url} → ${status}: ${(e as Error).message}`)
        host.switchToHttp().getResponse().status(status).json({ status })
    }
}
@Controller() @UseFilters(ServerErrorLogger) class C {
    @Get("bad") bad() { throw new BadRequestException("noto'g'ri parametr") }
    @Get("boom") boom() { throw new Error("null'ning xossasini o'qib bo'lmadi") }
}
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/bad")
    await http.get("/boom")
    console.log("Log'ga yozildi:", logged)
    await http.close()
}
main()

