import { appendFileSync, existsSync, mkdtempSync, readdirSync, renameSync, statSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

const dir = mkdtempSync(join(tmpdir(), "logs-"))
const MAX = 60, KEEP = 2
const file = (i: number) => join(dir, i === 0 ? "app.log" : `app.${i}.log`)
function write(line: string) {
    if (existsSync(file(0)) && statSync(file(0)).size + line.length > MAX) {
        for (let i = KEEP; i >= 1; i--) if (existsSync(file(i - 1))) renameSync(file(i - 1), file(i))
    }
    appendFileSync(file(0), line + "\n")
}
for (let i = 1; i <= 10; i++) write(`so'rov #${i} bajarildi`)
console.log(readdirSync(dir).sort().map(f => `${f} (${statSync(join(dir, f)).size} bayt)`))

