import { createHash } from "node:crypto"

const groups = new Map<string, { message: string; count: number }>()
function report(e: Error) {
    const normalized = e.message.replace(/\d+/g, "N")
    const fp = createHash("md5").update(`${e.name}:${normalized}`).digest("hex").slice(0, 8)
    const g = groups.get(fp) ?? { message: normalized, count: 0 }
    g.count++
    groups.set(fp, g)
}
for (const id of [5, 17, 42]) report(new Error(`Buyurtma ${id} topilmadi`))
report(new TypeError("Cannot read properties of undefined"))
report(new Error("Buyurtma 99 topilmadi"))
for (const [fp, g] of groups) console.log(fp, "×", g.count, "—", g.message)

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

function LogMethod() {
    return (_t: object, key: string | symbol, d: PropertyDescriptor) => {
        const original = d.value
        d.value = async function (this: object, ...args: unknown[]) {
            console.log(`→ ${this.constructor.name}.${String(key)}(${args.map(a => JSON.stringify(a)).join(", ")})`)
            try { const r = await original.apply(this, args); console.log(`← ${String(key)} natija:`, r); return r }
            catch (e) { console.log(`✗ ${String(key)} xato:`, (e as Error).message); throw e }
        }
    }
}
@Injectable() class PaymentsService {
    @LogMethod() async charge(userId: number, amount: number) { if (amount <= 0) throw new Error("summa musbat bo'lsin"); return { ok: true, userId, amount } }
}
