import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { tap } from "rxjs"

@Injectable() class DebugOnDemand implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const req = ctx.switchToHttp().getRequest()
        const debug = req.headers["x-debug"] === "1"
        if (debug) console.log(`DEBUG so'rov: ${req.method} ${req.url} query=${JSON.stringify(req.query)}`)
        return next.handle().pipe(tap(data => debug && console.log("DEBUG javob:", JSON.stringify(data))))
    }
}
@Controller("search") @UseInterceptors(DebugOnDemand) class S { @Get() s() { return { natija: 2 } } }
@Module({ controllers: [S] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/search?q=osh")
    await http.get("/search?q=osh", { "X-Debug": "1" })
    await http.close()
}
main()

